INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16901, 'Isaiah 19:6', 'Isaiah', 19, 6, '&nbsp;کله چې د درياب نِهرونه په کمېدو شى او اوچيږى نو د دې نه به خراب بوئ ځى. لوخې او جاړې به اوچې شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16902, 'Isaiah 19:7', 'Isaiah', 19, 7, '&nbsp;او د نيل درياب په غاړه چې څومره بوټى دى هغه به اوچ شى. او د درياب سره نزدې ټول کَرلے شوى پټى به اوچ شى او په هوا کښې به والوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16903, 'Isaiah 19:8', 'Isaiah', 19, 8, '&nbsp;ماهيګر به فرياد کوى او ژاړى به، د کُنډو او د جالونو والا به غمژن وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16904, 'Isaiah 19:9', 'Isaiah', 19, 9, '&nbsp;جولاګان او څوک چې د لټې جامې جوړوى به نااُميده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16905, 'Isaiah 19:10', 'Isaiah', 19, 10, '&nbsp;د کپړې جوړوونکى به سخت مايُوسه وى، او ټول کاريګر به پرېشانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16906, 'Isaiah 19:11', 'Isaiah', 19, 11, '&nbsp;د ضُعن ښار مشران کم عقل دى. د مِصر د بادشاه ښۀ هوښيار مشيران کم عقلې مشورې ورکوى. چې تاسو دا جرأت څنګه کولے شئ چې فِرعون بادشاه ته ووايئ چې، ”مونږ عالمانو شاګردان او د پخوانو بادشاهانو اولاد وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16907, 'Isaiah 19:12', 'Isaiah', 19, 12, '&nbsp;اے د مِصر بادشاه، ستا هغه هوښيار مشيران چرته دى؟ هغوئ دې معلوم کړى او تا ته دې ووائى چې مالِک خُدائ ربُ الافواج د مِصر دپاره څۀ منصوبې لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16908, 'Isaiah 19:13', 'Isaiah', 19, 13, '&nbsp;د ضُعن مشران کم عقل دى او د ميمفِس مشرانو دوکه خوړلې ده. دغه مشرانو مِصر بې‌لارې کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16909, 'Isaiah 19:14', 'Isaiah', 19, 14, '&nbsp;مالِک خُدائ هغوئ کم عقل کړى دى، نو د هغوئ ټولې مشورې غلطې دى. هغوئ مِصر داسې ګډ وډ کړے دے لکه چې يو شرابى په نشه کښې په خپلو اولټو کښې ښوئيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16910, 'Isaiah 19:15', 'Isaiah', 19, 15, '&nbsp;او مِصر به هيڅ هم نۀ شى کولے، کۀ مشر وى او کۀ کشر، کۀ لوئ وى او کۀ وړوکے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16911, 'Isaiah 19:16', 'Isaiah', 19, 16, '&nbsp;په هغه ورځ به مِصريان د ښځو په شان کمزورى وى. چې مالِک خُدائ ربُ الافواج هغوئ له د سزا ورکولو دپاره لاس اوچت کړى نو هغوئ به د يرې نه ولړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16912, 'Isaiah 19:17', 'Isaiah', 19, 17, '&nbsp;او د يهوداه مُلک په وجه به په مِصريانو باندې يره راشى، هر چا ته چې د يهوداه نوم واخستلے شى نو هغه به ويريږى، دا د هغه منصوبې په وجه چې مالِک خُدائ ربُ الافواج د هغوئ خِلاف تياره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16913, 'Isaiah 19:18', 'Isaiah', 19, 18, '&nbsp;په هغه وخت کښې به د مِصر په پينځو ښارونو کښې عبرانى ژبه وئيلے شى. د هغه ځائ خلق به د مالِک خُدائ ربُ الافواج په نوم د وفادارۍ قسمونه کوى. په هغه ښارونو کښې به د يو ښار نوم ”د نمر ښار“ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16914, 'Isaiah 19:19', 'Isaiah', 19, 19, '&nbsp;په هغه وخت کښې به د مِصر د مُلک په مينځ کښې د مالِک خُدائ دپاره يوه قربان‌ګاه وى او د مِصر په سرحد باندې به د کاڼى يو يادګار وى چې هغۀ ته وقف شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16915, 'Isaiah 19:20', 'Isaiah', 19, 20, '&nbsp;دا به په مِصر کښې د مالِک خُدائ ربُ الافواج د موجودګۍ نښې وى. کله چې هلته د خلقو سره ظلم زياتے کيږى او د مدد دپاره مالِک خُدائ ته آواز وکړى، نو هغه به د هغوئ د بچ کولو دپاره خلاصونکے ورلېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16916, 'Isaiah 19:21', 'Isaiah', 19, 21, '&nbsp;مالِک خُدائ به د مِصر خلقو ته خپل ځان څرګند کړى او هغوئ به يې قبول کړى او د هغۀ عبادت به کوى او هغۀ ته به قربانۍ او نذرانې پېش کوى. هغوئ به د هغۀ سره پاخۀ لوظونه وکړى او خپلې وعدې به ورسره پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16917, 'Isaiah 19:22', 'Isaiah', 19, 22, '&nbsp;مالِک خُدائ به مِصريانو له سزا ورکړى، خو هغه به يې بيا روغ کړى. هغوئ به هغۀ ته راوګرځى او هغه به د هغوئ سوال قبول کړى او هغوئ به روغ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16918, 'Isaiah 19:23', 'Isaiah', 19, 23, '&nbsp;په هغه وخت کښې به د مِصر او اسور په مينځ کښې يوه لويه لار وى. او د دواړو مُلکونو خلق به د يو بل مُلک ته ځى راځى او د مِصر او اسور قومونه به په يو ځائ عبادت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16919, 'Isaiah 19:24', 'Isaiah', 19, 24, '&nbsp;په هغه وخت کښې به بنى اِسرائيل د مِصر او اسور سره ملګرے شى او دا درې واړه قومونه به د ټولې دُنيا دپاره د برکت سبب جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16920, 'Isaiah 19:25', 'Isaiah', 19, 25, '&nbsp;مالِک خُدائ ربُ الافواج به دې قومونو له برکت ورکړى او ووبه فرمائى، ”اے مِصريانو، زما خلقو، اے اسوريانو، تاسو ما پېدا کړى يئ، اے بنى اِسرائيلو، تاسو زما غوره شوى خلق يئ نو تاسو له زۀ برکت درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16921, 'Isaiah 20:1', 'Isaiah', 20, 1, '&nbsp;په کوم کال چې د اسور د بادشاه د سرجون په حُکم د اسوريانو د لښکر فوجى مشر په اشدود ښار باندې حمله وکړه او دا يې قبضه کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16922, 'Isaiah 20:2', 'Isaiah', 20, 2, '&nbsp;په هغه وخت کښې مالِک خُدائ د آموص زوئ يشعياه ته فرمائيلى وُو چې هغه څپلۍ او د ټاټ هغه جامې وباسى کومې چې هغۀ اغوستې وې. نو هغۀ دا حُکم ومنلو او بربنډ او بغېر د څپلو نه روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16923, 'Isaiah 20:3', 'Isaiah', 20, 3, '&nbsp;نو بيا مالِک خُدائ وفرمائيل، ”زما خِدمت کوونکے يشعياه درې کاله بربنډ او بغېر د څپلو نه ګرځېدلے دے. دا د هغې نښه ده چې په مِصر او ايتهوپيا باندې به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16924, 'Isaiah 20:4', 'Isaiah', 20, 4, '&nbsp;د اسور بادشاه چې د دې دوو مُلکونو نه قېديان نيولى دى نو هغوئ به بربنډ بوځى. زلمى او بوډاګان به د څپلو نه بغېر او بربنډ روان وى، د هغوئ کوناټى به ښکارى، دا به د مِصر دپاره د شرم خبره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16925, 'Isaiah 20:5', 'Isaiah', 20, 5, '&nbsp;چا چې په ايتهوپيا باندې يقين ساتلے وى او په مِصر باندې يې لافې وهلې وى نو هغوئ به مايوسه شى او وبه شرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16926, 'Isaiah 20:6', 'Isaiah', 20, 6, '&nbsp;کله چې هغه وخت راشى نو کوم خلق چې د فلستيه د سمندر په غاړه اوسيږى نو هغوئ به ووائى، وګورئ، په هغه خلقو څۀ وشول چې په چا باندې مونږ دا يقين کولو چې مونږ به د اسور د بادشاه نه بچ کړى. خو اوس زمونږ دپاره د خلاصى لار هم نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16927, 'Isaiah 21:1', 'Isaiah', 21, 1, '&nbsp;دا پېغام د بابل په حقله دے، چې درياب سره په صحرا کښې دے. لکه څنګه چې په صحرا کښې تاوېدونکے باد چليږى دغه شان به افت د صحرا نه راشى، او يروونکے مُلک به درباندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16928, 'Isaiah 21:2', 'Isaiah', 21, 2, '&nbsp;ما د خرابو حالاتو په حقله يوه رويا يعنې د وېښې خوب ليدلے دے، ما وکتل چې دوکه باز دوکې کوى او تباه کار تباهى کوى. اے د عيلام لښکره، حمله وکړه. اے د مادى لښکره، ښار محاصره کړه. د بابل په وجه چې کوم مصيبت راغلے دے نو خُدائ پاک به هغه ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16929, 'Isaiah 21:3', 'Isaiah', 21, 3, '&nbsp;نو په دې وجه زۀ د يرې او درد سره مخ شوے يم، او دا درد داسې دے لکه چې ښځه يې د ماشوم د پېدا کولو په وخت لرى. زۀ چې څۀ اورم نو په ما بد لګى او چې څۀ ګورم نو يرېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16930, 'Isaiah 21:4', 'Isaiah', 21, 4, '&nbsp;زما زړۀ درزيږى او رپېږم. اول به ماښام په ما ډېر ښۀ لګېدو خو اوس د تيارې نه زۀ يرېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16931, 'Isaiah 21:5', 'Isaiah', 21, 5, '&nbsp;ګورم چې لوئ خوراک تياريږى، د خلقو د کښېناستو دپاره قالينونه غوړېدلى دى. هغوئ خوراک څښاک کوى، ”پاڅئ، اے آفسرانو، خپل ډالونه تيار کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16932, 'Isaiah 21:6', 'Isaiah', 21, 6, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”لاړ شه او يو محافظ ودروه او هر څيز چې هغه ګورى نو د هغې خبر به راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16933, 'Isaiah 21:7', 'Isaiah', 21, 7, '&nbsp;چې څنګه هغه دؤو آسونو والا جنګى ګاډۍ وګورى يا په خرونو او اوښانو باندې سوارۀ کسان ووينى، نو هغه دې ښۀ بېدار اوسى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16934, 'Isaiah 21:8', 'Isaiah', 21, 8, '&nbsp;بيا څوکيدار آواز وکړو، ”مالِکه خُدايه، زۀ په خپل ځائ باندې د څوکيدارۍ دپاره شپه او ورځ ولاړ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16935, 'Isaiah 21:9', 'Isaiah', 21, 9, '&nbsp;اوس وګورئ، د دؤو آسونو والا جنګى ګاډۍ راروانه ده چې يو سړے پکښې سور دے.“ څوکيدار ووئيل، ”بابل ختم شوے دے. د بابل ټول بُتان ټوټې ټوټې شوى دى او په زمکه باندې خوارۀ وارۀ پراتۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16936, 'Isaiah 21:10', 'Isaiah', 21, 10, '&nbsp;اے زما خلقو، تاسو د غنمو په شان په درمند باندې غوبل شوى يئ، خو اوس زۀ تاسو ته يو ښۀ زېرے اوروم چې ما د مالِک خُدائ ربُ الافواج نه اورېدلے دے، چې هغه د بنى اِسرائيلو خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16937, 'Isaiah 21:11', 'Isaiah', 21, 11, '&nbsp;دا پېغام د ادوم په حقله دے. د ادوم نه ما ته چا آواز وکړو، ”څوکيداره، دا شپه به کله تېريږى؟ سحر ته څومره وخت پاتې دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16938, 'Isaiah 21:12', 'Isaiah', 21, 12, '&nbsp;نو ما جواب ورکړو، ”سحر راتلونکے دے، خو شپه به بيا راځى. کۀ تۀ بيا تپوس کول غواړې، نو بيا راشه او تپوس وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16939, 'Isaiah 21:13', 'Isaiah', 21, 13, '&nbsp;دا پېغام د عربو په حقله دے. اے د ددان قافِلو، د عربو په شاړ مُلک کښې شپه تېره کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16940, 'Isaiah 21:14', 'Isaiah', 21, 14, '&nbsp;اے د تيما خلقو، کوم خلق چې تږى دى نو هغوئ له اوبۀ ورکوئ. او مهاجرو له خوراک ورکوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16941, 'Isaiah 21:15', 'Isaiah', 21, 15, '&nbsp;ځکه چې هغوئ د تُورو نه تښتى، او د داسې خلقو نه چې تُوره په لاس او تير کمان په غاړه د هغوئ سره سخت جنګېدلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16942, 'Isaiah 21:16', 'Isaiah', 21, 16, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”پوره په يو کال کښې دننه دننه به د قيدار شان او شوکت ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16943, 'Isaiah 21:17', 'Isaiah', 21, 17, '&nbsp;د قيدار صرف يو څو غشى او لينده چلوونکى سړى به پاتې شى. ما مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16944, 'Isaiah 22:1', 'Isaiah', 22, 1, '&nbsp;دا پېغام د رويا د وادۍ د يروشلم په حقله دے. څۀ شوى دى؟ دا ټول خلق ولې د کورونو چتونو ته د خوشحالۍ دپاره خېژى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16945, 'Isaiah 22:2', 'Isaiah', 22, 2, '&nbsp;ټول ښار بې‌قراره دے او د شور شرابې نه ډک دے. ستاسو مړى په تُوره نۀ دى قتل کړے شوى او نۀ په مېدانِ جنګ کښې مړۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16946, 'Isaiah 22:3', 'Isaiah', 22, 3, '&nbsp;ستاسو ټول مشران وتښتېدل او هغوئ لا يو غشے هم نۀ وو ويشتلے چې ونيولے شول. باقى خلقو هم د تښتېدو کوشش وکړو خو هغوئ هم قېد کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16947, 'Isaiah 22:4', 'Isaiah', 22, 4, '&nbsp;ځکه ما ووئيل، ”ما پرېږده چې په چغو چغو وژاړم. ما له د تسلۍ راکولو کوشش مۀ کوئ. ما پرېږدئ چې د خپلو خلقو دپاره وژاړم، زۀ ګورم چې هغوئ تباه کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16948, 'Isaiah 22:5', 'Isaiah', 22, 5, '&nbsp;په حقيقت کښې مالِک خُدائ، ربُ الافواج دا وخت راوستے دے. د رويا په وادۍ کښې ګډوډى ده، خلق هيبتناکې منډې وهى او د هغوئ د ژړا چغې غرونو ته رسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16949, 'Isaiah 22:6', 'Isaiah', 22, 6, '&nbsp;د عيلام د مُلک نه په آسونو سوارۀ فوجيان راغلل، چې کمان او غشى ورسره وُو. او د قير د مُلک فوجيانو خپل ډالونه راخستى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16950, 'Isaiah 22:7', 'Isaiah', 22, 7, '&nbsp;د يهوداه بهترينې واديانې د جنګى ګاډو نه ډکې وې، په آسونو سوارۀ فوجيان د يروشلم د دروازو په مخکښې حملې دپاره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16951, 'Isaiah 22:8', 'Isaiah', 22, 8, '&nbsp;يهوداه چې د خپل تحفُظ دپاره څومره بندوبست کړے وو هغه ختم شوے دے. په هغه ورځ تاسو څۀ وکړل؟ په هغه وخت کښې تاسو په هغه وسله باندې بهروسه وکړه کومه چې د ځنګل کور نومې ځائ کښې ساتلے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16952, 'Isaiah 22:11', 'Isaiah', 22, 11, '&nbsp;تاسو د ښار د دېوالونو په مينځ کښې د هغه اوبو رايسارولو دپاره تالاب جوړ کړو کومې اوبۀ چې د زوړ ډنډ نه رابهېدلې. خو تاسو خُدائ پاک ته هيڅ توجو ونۀ کړه، چې هغۀ ډېر د پخوا نه د دې هر څۀ منصوبه جوړه کړې وه او هغۀ داسې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16953, 'Isaiah 22:12', 'Isaiah', 22, 12, '&nbsp;بيا مالِک خُدائ پاک ربُ الافواج تاسو ته آوازونه کول چې ژړا او ماتم کوئ، خپل سرونه کل کړئ او د ټاټ جامې واغوندئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16954, 'Isaiah 22:13', 'Isaiah', 22, 13, '&nbsp;خو د هغې په ځائ، تاسو خندا او خوشحالى کوله. تاسو څاروى او ګډې حلالې کړې چې وې خورئ او تاسو مے څښل. تاسو وئيل، ”مونږ له ښۀ خوراک څښاک په کار دے، ځکه چې سبا به مړۀ يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16955, 'Isaiah 22:14', 'Isaiah', 22, 14, '&nbsp;مالِک خُدائ ربُ الافواج په خپله ما سره خبرې وکړې او راته يې وفرمائيل، ”ترڅو پورې چې تاسو ژوندى يئ نو دا بد عمل به درته هيڅکله معاف نۀ شى. ما، مالِک خُدائ پاک، ربُ الافواج دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16956, 'Isaiah 22:15', 'Isaiah', 22, 15, '&nbsp;مالِک خُدائ پاک، ربُ الافواج ما ته وفرمائيل چې، ”شبناه له لاړ شه، چې هغه د شاهى خاندان اِنتظام کوونکے دے او هغۀ ته ووايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16957, 'Isaiah 22:16', 'Isaiah', 22, 16, '&nbsp;تۀ دلته څۀ کوې؟ تا له دلته د خپل قبر جوړولو اجازت چا درکړے دے؟ تۀ څوک يې چې دلته به د ځان دپاره په اوچت ځائ کښې مزار جوړ کړې او په ګټ کښې د ځان دپاره قبر جوړ کړې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16958, 'Isaiah 22:17', 'Isaiah', 22, 17, '&nbsp;اے سړيه، مالِک خُدائ به دې راونيسى او لرې به دې وغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16959, 'Isaiah 22:18', 'Isaiah', 22, 18, '&nbsp;هغه به تا د پنډوسکى په شان ګول مول کړى او يو بل لوئ مُلک ته به دې وغورزوى. او تۀ به هلته مړ شې، او ستا ښائسته جنګى ګاډۍ به هم هلته پرتې وى. ولې چې تۀ د خپل نېک د خاندان دپاره د بې‌عزتۍ سبب جوړ شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16960, 'Isaiah 22:19', 'Isaiah', 22, 19, '&nbsp;مالِک خُدائ فرمائى، زۀ به تا د خپلې عُهدې نه لرې کړم او د خپل اوچت مقام نه به دې راکوز کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16961, 'Isaiah 22:20', 'Isaiah', 22, 20, '&nbsp;په هغه ورځ به زۀ خپل خِدمتګار د خِلقياه زوئ اِلياقيم راوغواړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16962, 'Isaiah 22:21', 'Isaiah', 22, 21, '&nbsp;زۀ به هغۀ ته ستا سرکارى چُوغه او کمربند ورواچوم او تا چې کوم اختيارات لرل نو هغه ټول به هغۀ له ورکړم. هغه به د يروشلم او د يهوداه د خلقو د پلار په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16963, 'Isaiah 22:22', 'Isaiah', 22, 22, '&nbsp;زۀ به هغۀ له د داؤد د خاندان چابيانې ورکړم. چې کومه دروازه هغه کولاو کړى هغه به څوک بندولے نۀ شى او چې کومه دروازه هغه بند کړى هغه به څوک کولاولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16964, 'Isaiah 22:23', 'Isaiah', 22, 23, '&nbsp;زۀ به هغۀ يوه لويه مرتبه ورکړم لکه څنګه چې په دېوال کښې مېخ کلک لګېدلے وى، او دا به د هغۀ د خاندان دپاره د عزت سبب وګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16965, 'Isaiah 22:24', 'Isaiah', 22, 24, '&nbsp;بيا به د هغۀ د پلار د خاندان ټول وزن په هغۀ باندې راځوړند شى. او د هغۀ ټول اولاد او خپلوان به د لوښو په شان د وړې پيالۍ نه واخله تر غټ مرتبان پورې به دې مېخ پورې راځوړند وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16966, 'Isaiah 22:25', 'Isaiah', 22, 25, '&nbsp;ربُ الافواج وفرمائيل، يو وخت به راشى چې دا کلک لګېدلے مېخ به راوغورزيږى او چې په دې باندې څۀ هم راځوړند وى نو هغه به مات شى. مالِک خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16967, 'Isaiah 23:1', 'Isaiah', 23, 1, '&nbsp;دا پېغام د صور په حقله دے. اے د ترسيس سمندرى جهازونو وژاړئ. ځکه چې په صور کښې قلعه او کورونه تباه دى، په قبرص کښې چې تاسو کومه خبره اورېدلې وه هغه رښتيا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16968, 'Isaiah 23:2', 'Isaiah', 23, 2, '&nbsp;اے د سمندر د غاړې اوسېدونکو ماتم وکړئ. اے د صيدا سوداګرو، تاسو ماتم وکړئ. ستاسو تاجران به د سمندر نه تېرېدل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16969, 'Isaiah 23:3', 'Isaiah', 23, 3, '&nbsp;او په ژورو اوبو کښې به يې سفر کولو او د مِصر غله به يې تاسو له رارسوله، ولې چې تاسو به د نيل د درياب د غاړې نه ګټه اخستله او دغه شان تاسو د ټولو قومونو دپاره د تجارت مرکز وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16970, 'Isaiah 23:4', 'Isaiah', 23, 4, '&nbsp;خو اوس تۀ شرمېدلے يې، اے د صيدا ښاريې. د سمندر قلعه بند ښار صور وائى، ”زۀ بې‌بچو يمه، زما هيڅ زامن او لوڼه نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16971, 'Isaiah 23:5', 'Isaiah', 23, 5, '&nbsp;کله چې مِصريانو ته د صور خبر مِلاو شى نو هغوئ به په غم اخته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16972, 'Isaiah 23:6', 'Isaiah', 23, 6, '&nbsp;اے د سمندر د غاړې خلقو، تاسو د خفګان نه وژاړئ. او ترسيس ته د تښتېدو کوشش وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16973, 'Isaiah 23:7', 'Isaiah', 23, 7, '&nbsp;آيا دا ستاسو خوشحاله ښار دے کوم چې ډېر د پخوا نه آباد دے؟ آيا دا هغه ښار دے چې خپل اوسېدونکى يې لرې مُلکونو ته ولېږل چې کورونه جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16974, 'Isaiah 23:8', 'Isaiah', 23, 8, '&nbsp;په صور باندې دا افت چا راوستے دے، هغه صور ښار چې به يې بادشاهتونه جوړول؟ د هغې سوداګر شهزادګان وُو او د هغې تاجران عزتمند ګڼلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16975, 'Isaiah 23:9', 'Isaiah', 23, 9, '&nbsp;خو دا د مالِک خُدائ ربُ الافواج منصوبه وه چې هغه به ټول د شان او شوکت والا خلق سپک کړى، او عزتمند کسان به وشرموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16976, 'Isaiah 23:10', 'Isaiah', 23, 10, '&nbsp;اے د ترسيس خلقو، د خپلې علاقې نه خوارۀ شئ لکه څنګه چې د نيل درياب د غاړو نه اوړى. نور تاسو پابند نۀ يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16977, 'Isaiah 23:11', 'Isaiah', 23, 11, '&nbsp;مالِک خُدائ په سمندر باندې لاس اوچت کړے دے او بادشاهۍ يې لړزولې دى. هغۀ حُکم کړے دے چې ستاسو قلعې دې تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16978, 'Isaiah 23:12', 'Isaiah', 23, 12, '&nbsp;هغۀ وفرمائيل، ”اے د صيدا خلقو، ستاسو خوشحالى ختمه شوې ده او ستاسو خلقو سره ظلم زياتے شوے دے. کۀ هغوئ قبرص ته هم وتښتى، نو آرام به ورته مِلاو نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16979, 'Isaiah 23:13', 'Isaiah', 23, 13, '&nbsp;د بابل مُلک ته وګورئ. د دې مُلک خلق برباد شوى دى. اسوريانو د هغوئ مُلک د ځنګلى ځناور کور جوړ کړے دے. اسوريانو د محاصرې برجونه جوړ کړل او د هغوئ قلعې يې بربادې کړې. او د ملبې ډېرے يې ترېنه جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16980, 'Isaiah 23:14', 'Isaiah', 23, 14, '&nbsp;اے د ترسيس سمندرى جهازونو د خفګان نه وژاړئ. ولې چې ستاسو قلعه تباه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16981, 'Isaiah 23:15', 'Isaiah', 23, 15, '&nbsp;يو داسې وخت راروان دے چې صور به اويا کاله دپاره هېر کړے شى، چې اويا کاله د يو بادشاه د عُمر برابر وى. کله چې هغه کالونه ختم شى، نو صور به بحال شى لکه څنګه چې سندره د کنجرې په حقله وئيلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16982, 'Isaiah 23:16', 'Isaiah', 23, 16, '&nbsp;”اے غريبې هېرې شوې کنجرې. خپله بينجو واخله او په ښار کښې وګرځه، ساز غږوه او خپلې سندرې بيا بيا وايه، نو چې داسې يو ځل بيا ياده کړے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16983, 'Isaiah 23:17', 'Isaiah', 23, 17, '&nbsp;کله چې هغه اويا کاله تېر شى، نو مالِک خُدائ به صور له موقع ورکړى چې هغه بيا د کنجرې په شان پخوانے کاروبار شروع شى او د صور لېن دېن به د زمکې په مخ د ټولو بادشاهتونو سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16984, 'Isaiah 23:18', 'Isaiah', 23, 18, '&nbsp;خو دا ښار چې په تجارت کښې کومه ګټه کوى نو هغه به مالِک خُدائ ته وقف کيږى. دا پېسه به نۀ شى جمع کولے، خو چې څوک د مالِک خُدائ په حضور کښې پاتې کيږى نو هغوئ به په دې پېسو باندې ښۀ کافى خوراک او ښائسته لباس اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16985, 'Isaiah 24:1', 'Isaiah', 24, 1, '&nbsp;ګوره، مالِک خُدائ به زمکه ورانه ويجاړه کړى او هم داسې شاړه به يې پرېږدى. هغه به د زمکې مخ کندې کپرې کړى او د دې خلق به خوارۀ وارۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16986, 'Isaiah 24:2', 'Isaiah', 24, 2, '&nbsp;هيڅ څوک به بچ پاتې نۀ شى، کۀ هغه اِمامان وى يا عام خلق، مالِک وى کۀ نوکر، مالِکه وى کۀ نوکره، خرڅوونکى وى يا اخستونکى، قرض ورکوونکى يا قرض اخستونکى، کۀ قرضدار وى او کۀ مالدار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16987, 'Isaiah 24:3', 'Isaiah', 24, 3, '&nbsp;زمکه به په مکمل طور ورانه ويجاړه او لوټ کړے شى، مالِک خُدائ دا هر څۀ فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16988, 'Isaiah 24:4', 'Isaiah', 24, 4, '&nbsp;زمکه اوچيږى او خُشکيږى، ټوله دُنيا به اوچه شى او مړاوې به شى، د دې لوئ لوئ خلق به فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16989, 'Isaiah 24:5', 'Isaiah', 24, 5, '&nbsp;خلقو دُنيا پليته کړې ده ځکه چې هغوئ د خُدائ پاک قانون مات کړے دے او هغه لوظ يې مات کړے دے کوم يې چې د همېشه دپاره ورسره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16990, 'Isaiah 24:6', 'Isaiah', 24, 6, '&nbsp;نو په دې وجه به زمکه لعنتى شى او نقصان به ورته ورسى، او چې د دې خلقو څۀ بد عمل کړے دے نو د هغې بدله ورته ملاويږى. نو په دې وجه د دُنيا خلق کم شول او ډېر لږ خلق ژوندى پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16991, 'Isaiah 24:7', 'Isaiah', 24, 7, '&nbsp;د انګورو بوټى اوچ شوى دى او مے کم شوى دى. هر څوک چې مخکښې خوشحاله وُو نو هغه اوس خفه دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16992, 'Isaiah 24:8', 'Isaiah', 24, 8, '&nbsp;او د هغوئ د رباب او د تمبل خوشحالۍ نه ډک سازونه او د جشن آوازونه بند شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16993, 'Isaiah 24:9', 'Isaiah', 24, 9, '&nbsp;اوس خلق د ميو سندرې نۀ وائى، بلکې شراب په هغوئ باندې تراخۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16994, 'Isaiah 24:10', 'Isaiah', 24, 10, '&nbsp;شاړ ښار برباد شوے دے او د هر يو کور دروازه کلکه بنده ده چې څوک ورننه نۀ وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16995, 'Isaiah 24:11', 'Isaiah', 24, 11, '&nbsp;په کوڅو کښې خلق چغې وهى چې مے ختم شوى دى. هره خوشحالى ختمه شوې ده، خوشحالى د زمکې نه ورکه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16996, 'Isaiah 24:12', 'Isaiah', 24, 12, '&nbsp;ښار په کنډر بدل شوے دے او د دې دروازې ذرې ذرې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16997, 'Isaiah 24:13', 'Isaiah', 24, 13, '&nbsp;نو په ټوله دُنيا کښې هر يو قوم سره به هم داسې کيږى. صرف لږ خلق به پاتې شى داسې لکه چې د زيتُونو راټولولو نه پس هم لږ پاتې وى او يا د انګورو د راشوکولو نه پس هم په باغ کښې يو څو دانې پاتې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16998, 'Isaiah 24:14', 'Isaiah', 24, 14, '&nbsp;خو چې کوم لږ کسان ژوندى پاتې وى نو هغوئ به د خوشحالۍ سندرې وائى. څوک چې د نمرپرېواتۀ طرف ته وى هغوئ به د مالِک خُدائ لوئى بيانوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16999, 'Isaiah 24:15', 'Isaiah', 24, 15, '&nbsp;د نمرخاتۀ په طرف مُلکونو کښې د مالِک خُدائ ثناء صِفت کوئ. کوم خلق چې د سمندر په غاړه اوسيږى نو هغوئ دې د مالِک خُدائ ثناء صِفت کوى، کوم چې د بنى اِسرائيلو خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17000, 'Isaiah 24:16', 'Isaiah', 24, 16, '&nbsp;مونږ د دُنيا د آخرى سرونو نه سندرې اورو، هغه سندرې چې صادق خُدائ پاک ته لوئى ورکوى. خو زما زړۀ د غمه ډک دے. زما دپاره ژاړئ ځکه چې زۀ دوړېږم. دوکې تر اوسه موجودى دى او هر طرف ته دوکه باز دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');